fn client(server: &MockServer) -> MisarDev {
    MisarDev::builder()
        .api_key("mdk_test_key")
        .base_url(format!("{}/dev", server.uri()))
        .build()
        .expect("client")
}

fn url_of(req: &wiremock::Request) -> String {
    match req.url.query() {
        Some(q) => format!("{}?{}", req.url.path(), q),
        None => req.url.path().to_owned(),
    }
}

#[test]
fn table_covers_every_operation() {
    assert_eq!(OPERATIONS.len() + STREAMS.len(), super::OPERATION_COUNT);
}

#[tokio::test]
async fn every_generated_method_builds_its_route() {
    let server = MockServer::start().await;
    for (name, verb, url, has_body, call) in OPERATIONS {
        server.reset().await;
        Mock::given(any())
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({"ok": true})))
            .mount(&server)
            .await;
        let dev = client(&server);
        let out = call(&dev).await.unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(out, json!({"ok": true}), "{name}");
        let reqs = server.received_requests().await.expect("recording");
        assert_eq!(reqs.len(), 1, "{name}");
        assert_eq!(reqs[0].method.as_str(), *verb, "{name}");
        assert_eq!(url_of(&reqs[0]), format!("/dev{url}"), "{name}");
        if *has_body {
            let body: Value = serde_json::from_slice(&reqs[0].body).expect("json body");
            assert_eq!(body["probe"], json!(true), "{name}");
        }
    }
}

#[tokio::test]
async fn every_generated_stream_builds_its_route() {
    let server = MockServer::start().await;
    for (name, verb, url, has_body, call) in STREAMS {
        server.reset().await;
        Mock::given(any())
            .respond_with(
                ResponseTemplate::new(200)
                    .insert_header("content-type", "text/event-stream")
                    .set_body_string("data: {\"x\":1}\n\n"),
            )
            .mount(&server)
            .await;
        let dev = client(&server);
        let mut stream = call(&dev).await.unwrap_or_else(|e| panic!("{name}: {e}"));
        let mut n = 0;
        while let Some(ev) = stream.next().await {
            assert_eq!(ev.expect("event").data, json!({"x": 1}), "{name}");
            n += 1;
        }
        assert_eq!(n, 1, "{name}");
        let reqs = server.received_requests().await.expect("recording");
        assert_eq!(reqs[0].method.as_str(), *verb, "{name}");
        assert_eq!(url_of(&reqs[0]), format!("/dev{url}"), "{name}");
        if *has_body {
            let body: Value = serde_json::from_slice(&reqs[0].body).expect("json body");
            assert_eq!(body["probe"], json!(true), "{name}");
        }
    }
}
